package com.masterlearning.platform.modules.program.entity;
import com.masterlearning.platform.common.entity.BaseEntity; import com.masterlearning.platform.modules.course.entity.Course; import jakarta.persistence.*; import java.util.UUID;
@Entity @Table(name="learning_path_courses",uniqueConstraints=@UniqueConstraint(columnNames={"learning_path_id","course_id"})) public class LearningPathCourse extends BaseEntity { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="learning_path_id",nullable=false) private LearningPath learningPath; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="course_id",nullable=false) private Course course; @Column(name="sort_order",nullable=false) private int sortOrder; protected LearningPathCourse(){} public LearningPathCourse(LearningPath p,Course c,int o){learningPath=p;course=c;sortOrder=o;} public UUID getId(){return id;} }